old_string:
form.addEventListener("submit", async (e) => {
  e.preventDefault();
  const formData = bridge.getFormData(form);

  const body: AdminSettingsSaveRequest = {
    batch_size: parseInt(String(formData.batch_size), 10),
    quiet_hours_start: String(formData.quiet_hours_start),
    quiet_hours_end: String(formData.quiet_hours_end),
    conversion_attribution_window_days: parseInt(
      String(formData.conversion_attribution_window_days),
      10,
    ),
  };

